"""Merkle tree of SHA-256 over fixed chunks vs sequential, throughput test.
Also test: parallel hash of chunks + sequential combine of the (tiny) digests.
"""
import os, time, hashlib
from concurrent.futures import ThreadPoolExecutor

data = os.urandom(20_000_000)

def serial():
    return hashlib.sha256(data).digest()

def chunked_parallel(nthreads, chunk):
    n = len(data)
    ranges = []
    i = 0
    while i < n:
        ranges.append((i, min(i+chunk, n)))
        i += chunk
    def h(r):
        return hashlib.sha256(data[r[0]:r[1]]).digest()
    with ThreadPoolExecutor(nthreads) as ex:
        digests = list(ex.map(h, ranges))
    # combine
    return hashlib.sha256(b''.join(digests)).digest()

t0=time.perf_counter()
for _ in range(3): serial()
print('serial', (time.perf_counter()-t0)/3)

for nt in (4, 6, 8):
    for ch in (1<<20, 1<<18, 1<<16):
        t0=time.perf_counter()
        for _ in range(3): chunked_parallel(nt, ch)
        print(f'threads={nt} chunk={ch//1024}KB', (time.perf_counter()-t0)/3)
